function matchingPairs(n: number, queries: number[][]): number[] {
  const colors = new Array(n).fill(0);
  const out: number[] = [];
  for (const [i, c] of queries) {
    colors[i] = c;
    let count = 0;
    for (let j = 0; j + 1 < n; j++) if (colors[j] !== 0 && colors[j] === colors[j + 1]) count++;
    out.push(count);
  }
  return out;
}

